import json

# Try: output reflects which 2x2 blocks CONTAIN a 0
# And we'd show this as 0s in output

grid = [
    [5, 5, 5, 5, 1, 5],
    [5, 5, 0, 5, 5, 5],
    [5, 5, 5, 5, 5, 5],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 0, 5, 5, 5],
    [5, 0, 5, 0, 5, 5]
]

output = [[5]*3 for _ in range(3)]  # Start with 5s

for i in range(3):
    for j in range(3):
        r0, c0 = i*2, j*2
        has_zero = False
        for r in range(r0, r0+2):
            for c in range(c0, c0+2):
                if grid[r][c] == 0:
                    has_zero = True
                    break
        if has_zero:
            output[i][j] = 0
        else:
            # Check if this block has a 1
            has_one = False
            for r in range(r0, r0+2):
                for c in range(c0, c0+2):
                    if grid[r][c] == 1:
                        has_one = True
                        break
            if has_one:
                output[i][j] = 1

print("Output (0 where block has 0, 1 where block has 1):")
for row in output:
    print(row)

print("\nSubmitting...")
print(json.dumps({"action": "submit", "grid": output}))

