import json

# Clean up the None fill - use 0 or 5
grid = [
    [5, 5, 5, 5, 1, 5],
    [5, 5, 0, 5, 5, 5],
    [5, 5, 5, 5, 5, 5],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 0, 5, 5, 5],
    [5, 0, 5, 0, 5, 5]
]

# Option 1: Last value wins, None becomes 0
output1 = [[0]*3 for _ in range(3)]
for r in range(6):
    for c in range(6):
        if grid[r][c] != 5:
            i, j = r // 2, c // 2
            output1[i][j] = grid[r][c]

print("Option 1 (with 0 fill):")
for row in output1:
    print(row)
print(json.dumps({"action": "submit", "grid": output1}))

# Option 2: Last value wins, None becomes 5
output2 = [[5]*3 for _ in range(3)]
for r in range(6):
    for c in range(6):
        if grid[r][c] != 5:
            i, j = r // 2, c // 2
            output2[i][j] = grid[r][c]

print("\nOption 2 (with 5 fill):")
for row in output2:
    print(row)
print(json.dumps({"action": "submit", "grid": output2}))

# Option 3: First value wins
output3 = [[None]*3 for _ in range(3)]
for r in range(6):
    for c in range(6):
        if grid[r][c] != 5:
            i, j = r // 2, c // 2
            if output3[i][j] is None:
                output3[i][j] = grid[r][c]
output3_last = [[v if v else 0 for v in row] for row in output3]
print("\nOption 3 (first value, with 0 fill):")
for row in output3_last:
    print(row)
print(json.dumps({"action": "submit", "grid": output3_last}))

import json

# What if the output should have 1 at position (0,2) and ALSO have some other pattern?
# Maybe the output should FULLY represent both the 1 and the 0s?

# Try: output with 1 where input has 1, 0 where input has 0, 5 where background
# But this won't fit in 3x3 unless I scale

# Alternative: maybe each byte tells something different about each block?
# Like: 0 = empty, 1 = has 1, 2 = has 0?

grid = [
    [5, 5, 5, 5, 1, 5],
    [5, 5, 0, 5, 5, 5],
    [5, 5, 5, 5, 5, 5],
    [0, 5, 0, 5, 5, 5],
    [0, 0, 0, 5, 5, 5],
    [5, 0, 5, 0, 5, 5]
]

output_special = [[5]*3 for _ in range(3)]  # 5 = unknown/empty
pattern = {}

for i in range(3):
    for j in range(3):
        r0, c0 = i*2, j*2
        values = set(grid[r][c] for r in range(r0, r0+2) for c in range(c0, c0+2))
        non_bg = values - {5}
        if len(non_bg) > 0:
            if 1 in non_bg and 0 not in non_bg:
                pattern[(i,j)] = 1  # only 1s
            elif 0 in non_bg and 1 not in non_bg:
                pattern[(i,j)] = 0  # only 0s
            else:
                pattern[(i,j)] = 2  # both 0 and 1 (rare but possible)
        else:
            pass  # remains 5 (empty)

print("Special encoding (0=has 0, 1=has 1, 2=has both, 5=empty):")
for i in range(3):
    row = []
    for j in range(3):
        row.append(pattern.get((i,j), 5))
    print(row)

print(json.dumps({"action": "submit", "grid": output_special}))

